def fill_category_slugs(apps, schema_editor):
    Category = apps.get_model("finance", "Category")
    used = set()
    for category in Category.objects.order_by("owner_id", "id"):
        base = slugify(category.name, allow_unicode=True) or "category"
        candidate = base
        suffix = 2
        while (category.owner_id, candidate) in used:
            candidate = f"{base}-{suffix}"
            suffix += 1
        category.slug = candidate
        category.save(update_fields=["slug"])
        used.add((category.owner_id, candidate))


